'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V5a4 4 0 0 1 8 0v3"/>',user:'<circle cx="12" cy="7" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`;
const arrow='<span class="arrow" aria-hidden="true">⟶</span>';
const cats=['Cookware','Serveware & hotcases','Mugs & cups','Bottles & flasks','Lunchboxes & tiffins','Storage','Kitchen & home utility'];
const chapters={cook:'Cookware',gather:'Serveware & hotcases',pause:'Mugs & cups',carry:'Lunchboxes & tiffins'};
let catalog=[], stats={}, pdpQty=1, toastTimer;
let cart=readStore('atelier-review-bag',[]), orders=readStore('atelier-review-orders',[]);
function readStore(key,fallback){try{const a=JSON.parse(localStorage.getItem(key));return Array.isArray(a)?a:fallback}catch{return fallback}}
function saveStore(key,data){try{localStorage.setItem(key,JSON.stringify(data))}catch{toast('Browser storage is unavailable. This session may not be saved.')}}
const product=id=>catalog.find(p=>p.id===id);
const categoryUrl=c=>'#/shop?category='+encodeURIComponent(c);
const productUrl=(p,v)=>`#/product/${p.id}${v?'?variant='+v:''}`;
function photo(key,cls='',priority=false){const ids={cook:'kadai',gather:'olivia-2500',pause:'saucepan',carry:'sleek-lunch-box','carry-close':'sleek-lunch-box','carry-bag':'sleek-lunch-box'};const id=ids[key]||'kadai';return `<picture${cls?` class="${cls}"`:''}><img src="${esc(product(id).heroSource)}" alt="${esc(product(id)?.name||'Courtyard product study')} — AI-assisted courtyard scene" ${priority?'fetchpriority="high"':'loading="lazy"'} width="1254" height="1254"></picture>`}
const wordmark=()=>'<span class="wordmark"><b>ATELIER 00</b><small>A TEMPORARY WORDMARK</small></span>';
function chrome(){
 $('#header').innerHTML=`<button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><a href="#/" aria-label="Atelier 00 home">${wordmark()}</a><nav class="desktop-nav" aria-label="Main navigation"><a href="#/shop">Shop all</a><a href="#/collections">Collections</a><a href="#/names">The naming study</a><a href="#/story">Our perspective</a><a href="#/help">Help & care</a></nav><div class="nav-tools"><button class="icon-button" aria-label="Search products" data-action="search">${icon('search')}</button><a class="icon-button account-icon" href="#/account" aria-label="Guest orders">${icon('user')}</a><button class="icon-button" data-action="bag" aria-label="Open review bag">${icon('bag')}<span class="bag-label">Bag</span><span id="bag-count" aria-live="polite">(0)</span></button></div>`;
 $('#footer').innerHTML=`<div class="footer-top"><div class="footer-brand"><a href="#/">${wordmark()}</a><p>For what you cook.<br>For whom you gather.<br>For the day you carry with you.</p></div><div class="footer-col"><h4>EXPLORE</h4><a href="#/shop">All objects</a><a href="${categoryUrl(cats[0])}">Cook</a><a href="${categoryUrl(cats[1])}">Gather</a><a href="${categoryUrl(cats[2])}">Pause</a><a href="${categoryUrl(cats[4])}">Carry</a></div><div class="footer-col"><h4>HERE TO HELP</h4><a href="#/help">Help & care</a><a href="#/track">Track a review order</a><a href="#/policy/shipping">Shipping & delivery</a><a href="#/policy/returns">Returns</a><a href="#/support">Contact & support</a></div><div class="footer-col"><h4>A CLOSER LOOK</h4><a href="#/story">Our perspective</a><a href="#/names">The naming study</a><a href="#/account">Guest orders</a><a href="#/policy/privacy">Privacy</a><a href="#/policy/terms">Terms</a><a href="#/launch">Launch & review notes</a></div></div><div class="footer-bottom"><span>ATELIER 00 · Temporary identity · Storefront preview edition</span><span>Ancient India-inspired courtyard imagery · Original product photos in the galleries.</span></div>`;
 updateBagCount();
}
function updateBagCount(){$('#bag-count').textContent=`(${cart.reduce((s,x)=>s+x.qty,0)})`}
function card(p,filterColor=''){const color=typeof filterColor==='string'?filterColor:'';const v=(color?p.variants.find(v=>v.label.toLowerCase().includes(color.toLowerCase())):null)||p.variants.find(v=>v.id===p.heroVariant)||p.variants[0];return `<article class="product-card"><a href="${productUrl(p,v.id)}"><div class="card-image"><img src="${v.gallery[0].src}" alt="${esc(p.name)} — ${esc(v.label)}" loading="lazy" width="600" height="600"><span class="card-kicker">${!p.verifiedOriginals?'Image verification pending':p.materialUncertain?'Material to confirm':p.range+' / The courtyard edit'}</span><span class="card-arrow" aria-hidden="true">↗</span></div><div class="card-meta"><h3>${esc(p.name)}</h3><span>${p.variants.length>1?p.variants.length+' options':''}</span></div><p class="card-category">${esc(p.category)}</p><p class="card-status">Price & availability coming soon</p></a></article>`}
function selectedCards(ids){return ids.map(id=>product(id)).filter(Boolean).map(p=>card(p,p.id==='sleek-lunch-box'?'Green':'')).join('')}
function mini(id,link,label){const p=product(id);return `<div class="shop-strip"><span class="eyebrow">IN THE MOMENT</span><a class="mini-product" href="${productUrl(p)}"><img src="${p.variants[0].gallery[0].src}" alt="${esc(p.name)}" loading="lazy"><div><b>${esc(p.name)}</b><small>Explore the original product</small></div></a><div class="mini-links"><a class="text-link" href="${productUrl(p)}">Meet the object ${arrow}</a><a class="text-link" href="${link}">${label} ${arrow}</a></div></div>`}
function home(){return `
<section class="courtyard-hero" id="cook">
 <div class="courtyard-hero-copy"><span class="ornament" aria-hidden="true">✧</span><span class="eyebrow">THE COURTYARD EDIT / STUDY 02</span><h1>See steel<br>differently.</h1><p>Familiar forms. A timeless setting.<br>For the way we cook, gather, and live.</p><a class="button light" href="${categoryUrl(cats[0])}">Discover Agni cookware ${arrow}</a><a class="quiet-link" href="#/names">A new language for the everyday ↗</a><span class="hero-footnote">ANCIENT INDIA, REIMAGINED.<br>YOUR ACTUAL PRODUCTS, SEEN ANEW.</span></div>
 <a class="courtyard-hero-image" href="${productUrl(product('kadai'),'v2')}"><img src="${esc(product('kadai').heroSource)}" alt="Agni Kadai cooking vegetables in the generated sandstone-and-emerald courtyard scene" fetchpriority="high" width="1254" height="1254"><span class="hero-object-caption"><small>01 / THE FIRST SIZZLE</small><b>Agni Kadai</b><span>Explore the object ↗</span></span></a>
</section>
<nav class="chapters courtyard-chapters" aria-label="Explore four everyday moments">${Object.keys(chapters).map((k,i)=>`<a href="#/?chapter=${k}"><span>0${i+1}</span> ${k.toUpperCase()} <small>${['Agni / The hearth','Bhoj / The table','Rasa / The pause','Yatra / The journey'][i]}</small></a>`).join('')}</nav>
<section class="courtyard-intro section"><div><span class="eyebrow">ROOTED IN THE EVERYDAY</span><h2>A courtyard.<br>A thousand small rituals.</h2></div><div><p>Stone warmed by the sun. Woven cotton. A quiet green wall. And the familiar gleam of steel.</p><p>We bring an older Indian sensibility to the objects already around us—through setting, rhythm, and a shared language of names.</p><a class="text-link" href="#/names">Meet the seven product families ${arrow}</a></div></section>
<section class="section courtyard-selection"><div class="section-head"><div><span class="eyebrow">FAMILIAR OBJECTS. NEW NAMES.</span><h2>Everyday, with presence.</h2></div><a class="text-link" href="#/shop">Explore all 72 families ${arrow}</a></div><div class="products">${selectedCards(['kadai','olivia-2500','apple-sober-cup','sleek-lunch-box'])}</div><p class="collection-disclosure">Courtyard imagery created from supplied product references. Original photographs remain available in the product galleries.</p></section>
<section class="courtyard-editorial" id="gather"><a class="courtyard-editorial-image" href="${productUrl(product('olivia-2500'))}"><img src="${esc(product('olivia-2500').heroSource)}" alt="Bhoj Sabha Hotcase with its domed steel lid in the courtyard collection" loading="lazy" width="1254" height="1254"><span class="photo-caption">Bhoj Sabha Hotcase 2500 / Original catalog: Olivia 2500</span></a><div class="courtyard-editorial-copy"><span class="rule"></span><span class="eyebrow">02 / BHOJ — GATHER</span><h2>Good food brings us here.<br>Good company keeps us.</h2><p>A place for the food you make.<br>And the people who stay.</p><a class="text-link" href="${categoryUrl(cats[1])}">Gather around Bhoj ${arrow}</a></div></section>
<section class="section courtyard-pause" id="pause"><div class="section-head"><div><span class="eyebrow">03 / RASA — THE EVERYDAY PAUSE</span><h2>Let the conversation steep.</h2></div><p>Ginger. Milk. Tea.<br>A moment worth making room for.</p><a class="text-link" href="${categoryUrl(cats[2])}">Discover Rasa ${arrow}</a></div><div class="courtyard-duo"><a href="${productUrl(product('saucepan'))}"><img src="${esc(product('saucepan').heroSource)}" alt="Agni Dhara Saucepan with its twin-wire black-sleeved handle" loading="lazy" width="1254" height="1254"><div><span class="eyebrow">THE PREPARATION</span><h3>Agni Dhara Saucepan</h3><span class="text-link">A familiar beginning ${arrow}</span></div></a><a href="${productUrl(product('apple-sober-cup'))}"><img src="${esc(product('apple-sober-cup').heroSource)}" alt="Rasa Prabhat Cup in warm courtyard sunlight" loading="lazy" width="1254" height="1254"><div><span class="eyebrow">THE PAUSE</span><h3>Rasa Prabhat Cup</h3><span class="text-link">A moment to keep ${arrow}</span></div></a></div></section>
<section class="courtyard-editorial courtyard-carry" id="carry"><div class="courtyard-editorial-copy"><span class="rule"></span><span class="eyebrow">04 / YATRA — CARRY</span><h2>A little home.<br>Wherever the<br>day goes.</h2><p>Pack what you love.<br>Take the familiar with you.</p><a class="text-link" href="${categoryUrl(cats[4])}">Take Yatra into your day ${arrow}</a><a class="quiet-link" href="${categoryUrl(cats[3])}">Jal bottles & flasks ↗</a></div><a class="courtyard-editorial-image" href="${productUrl(product('sleek-lunch-box'),'v2')}"><img src="${esc(product('sleek-lunch-box').heroSource)}" alt="Yatra Saancha Lunchbox with its original turquoise lid in the courtyard setting" loading="lazy" width="1254" height="1254"><span class="photo-caption">Yatra Saancha Lunchbox / Original catalog: Sleek Lunch Box</span></a></section>
<section class="courtyard-names-banner"><span class="ornament" aria-hidden="true">✧</span><p>Agni. Bhoj. Rasa. Jal.<br>Yatra. Nidhi. Sutra.</p><span class="eyebrow">SEVEN FAMILIES. ONE SHARED WORLD.</span><a class="text-link" href="#/names">Explore the naming study ${arrow}</a></section>
<section class="section"><div class="section-head"><div><span class="eyebrow">FIND YOUR EVERYDAY</span><h2>A place for every ritual.</h2></div><a class="text-link" href="#/shop">The full collection ${arrow}</a></div>${collectionTiles()}</section>`}

function namingStudy(){const ranges=[['Agni','Cookware','For the first preparation.','kadai'],['Bhoj','Serveware & hotcases','For a table with room for more.','olivia-2500'],['Rasa','Mugs & cups','For a moment worth keeping.','apple-sober-cup'],['Jal','Bottles & flasks','For the water you carry.','stylo-1000'],['Yatra','Lunchboxes & tiffins','For a little home along the way.','sleek-lunch-box'],['Nidhi','Storage','For the things you keep close.','golmaal-steel-container'],['Sutra','Kitchen & home utility','For the small acts that hold a home together.','whisk-1-2-3']];return `<div class="page-head naming-heading"><span class="eyebrow">THE COURTYARD NAMING STUDY / 72 PRODUCT FAMILIES</span><h1>A shared language.<br>A familiar purpose.</h1><p>Indian-language-inspired range names, paired with clear product descriptions. Proposed creative names for your review; final selection and name clearance remain pending.</p></div><section class="section"><div class="range-study-grid">${ranges.map(([range,category,line,id],i)=>`<a class="range-study-card" href="${categoryUrl(category)}"><img src="${esc(product(id).heroSource)}" alt="${esc(product(id).name)}" loading="lazy" width="800" height="800"><div><span class="eyebrow">0${i+1} / ${esc(category)}</span><h2>${range}</h2><p>${line}</p><span class="text-link">Explore the family ${arrow}</span></div></a>`).join('')}</div><div class="section-head" style="margin-top:65px"><div><span class="eyebrow">EVERY FAMILY, ACCOUNTED FOR</span><h2>The complete name study.</h2></div></div><p class="small-note">The original catalog name remains searchable. Existing product IDs, source folders, colours, sizes and product markings are preserved. Model numbers are not treated as capacity.</p><div class="naming-table-wrap"><table class="status-table naming-table"><thead><tr><th>Original catalog name</th><th>Proposed product name</th><th>Family</th></tr></thead><tbody>${catalog.map(p=>`<tr><td>${esc(p.sourceName)}</td><td><a href="${productUrl(p)}">${esc(p.name)} ↗</a></td><td>${esc(p.range)}</td></tr>`).join('')}</tbody></table></div><div class="notice">The courtyard is a contemporary creative interpretation inspired by older Indian materials and architectural detail. These modern products are not presented as historical artifacts or as evidence of a claimed company heritage.</div></section>`}

function collectionTiles(){const ids=['kadai','olivia-2500','apple-sober-cup','stylo-1000','sleek-lunch-box','golmaal-steel-container','whisk-1-2-3'];return `<div class="collections-grid">${cats.map((c,i)=>{const p=product(ids[i])||catalog.find(p=>p.category===c);return `<a class="collection-tile" href="${categoryUrl(c)}"><div><span class="eyebrow">0${i+1} / THE COLLECTION</span><h3>${esc(c)} <span aria-hidden="true">↗</span></h3><small>${catalog.filter(p=>p.category===c).length} product families</small></div><img src="${(p.variants.find(v=>v.id===p.heroVariant)||p.variants[0]).gallery[0].src}" alt="" loading="lazy"></a>`}).join('')}</div>`}
function collections(){return `<div class="page-head"><span class="eyebrow">THE WAY WE COOK, GATHER & LIVE</span><h1>Seven families.<br>One shared world.</h1><p>From the first preparation to a little home carried into the day.</p></div><section class="section">${collectionTiles()}</section>`}
let shopState={category:'',q:'',color:'',verified:false,sort:'featured'};
function shop(params){shopState={category:params.get('category')||'',q:params.get('q')||'',color:params.get('color')||'',verified:params.get('verified')==='1',sort:params.get('sort')||'featured'};const c=shopState.category;return `<div class="page-head"><div class="breadcrumb"><a href="#/">Home</a><span>/</span><a href="#/collections">Collections</a></div><span class="eyebrow">THE COURTYARD COLLECTION</span><h1>${esc(c||'Familiar forms. A fresh spirit.')}</h1><p>${c?'Familiar forms, thoughtfully seen. Explore the collection.':'Cookware, homeware and the things you reach for, again and again.'}</p></div><div class="catalog-layout"><aside class="filters" aria-label="Product filters"><h3>EXPLORE & REFINE</h3><div class="filter-cats"><button class="filter-cat ${!c?'active':''}" data-action="filter-category" data-category="">All objects</button>${cats.map(cat=>`<button class="filter-cat ${c===cat?'active':''}" data-action="filter-category" data-category="${esc(cat)}">${esc(cat)}</button>`).join('')}</div><div class="filter-block"><label for="catalog-search">LOOKING FOR SOMETHING?</label><input id="catalog-search" type="search" placeholder="Search names & options" value="${esc(shopState.q)}"></div><div class="filter-block"><label for="color-filter">CATALOG COLOUR</label><select id="color-filter"><option value="">All colours</option>${['Blue','Green','Pink','Black','White','Ivory','Peach','Violet','Grey','Orange','Golden','Brown','Red','Yellow','Silver','Turquoise'].map(x=>`<option ${shopState.color===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="filter-block"><label class="check"><input id="verified-filter" type="checkbox" ${shopState.verified?'checked':''}>Original photos supplied</label><button class="text-button" data-action="reset-filters">Clear filters</button></div><p class="small-note">Colours follow the source folder labels. Prices and availability are pending.</p></aside><section><div class="catalog-top"><span id="result-count" role="status"></span><label>Sort: <select id="sort-filter"><option value="featured">Curated order</option><option value="az" ${shopState.sort==='az'?'selected':''}>Name A–Z</option><option value="za" ${shopState.sort==='za'?'selected':''}>Name Z–A</option></select></label></div><div class="products" id="catalog-results"></div></section></div>`}
function matchProduct(p,q){return (p.name+' '+p.sourceName+' '+p.range+' '+p.category+' '+p.variants.map(v=>v.label).join(' ')).toLowerCase().includes(q.toLowerCase())}
function updateShop(){let a=catalog.filter(p=>(!shopState.category||p.category===shopState.category)&&(!shopState.q||matchProduct(p,shopState.q))&&(!shopState.color||p.variants.some(v=>v.label.toLowerCase().includes(shopState.color.toLowerCase())))&&(!shopState.verified||p.verifiedOriginals));const curated=['kadai','olivia-2500','saucepan','apple-sober-cup','sleek-lunch-box','zaika'];if(shopState.sort==='az')a.sort((x,y)=>x.name.localeCompare(y.name));else if(shopState.sort==='za')a.sort((x,y)=>y.name.localeCompare(x.name));else a.sort((x,y)=>{const xi=curated.indexOf(x.id),yi=curated.indexOf(y.id);return (xi<0?999:xi)-(yi<0?999:yi)});$('#result-count').textContent=`${a.length} product ${a.length===1?'family':'families'}${shopState.q?' matching “'+shopState.q+'”':''}`;$('#catalog-results').innerHTML=a.length?a.map(p=>card(p,shopState.color)).join(''):`<div class="empty"><h2>A little further afield.</h2><p>No products match these filters. Try another name or clear the filters.</p><button class="button" data-action="reset-filters">Show all objects ${arrow}</button></div>`;const q=new URLSearchParams;for(const [k,v]of Object.entries(shopState)){if(v&&v!=='featured')q.set(k,v===true?'1':v)}history.replaceState(null,'','#/shop'+(q.size?'?'+q:''))}
function renderProduct(p,vi=0,qty=1){vi=Math.max(0,Math.min(vi,p.variants.length-1));const v=p.variants[vi];const img=v.gallery[0];const scene={kadai:'cook','olivia-2500':'gather',saucepan:'pause','apple-sober-cup':'pause','sleek-lunch-box':'carry'}[p.id];return `<article class="pdp" data-product="${p.id}" data-variant="${v.id}"><div class="breadcrumb"><a href="#/">Home</a><span>/</span><a href="${categoryUrl(p.category)}">${esc(p.category)}</a><span>/</span><span>${esc(p.name)}</span></div><div class="pdp-grid"><div><div class="gallery-main"><button data-action="zoom" aria-label="Enlarge product photograph"><img id="product-main-image" src="${img.src}" alt="${esc(p.name)} — ${esc(v.label)}" width="1200" height="1200"></button><span class="zoom-note">Click to look closer ↗</span></div><div class="gallery-thumbs" aria-label="Product gallery">${v.gallery.map((im,i)=>`<button class="${!i?'active':''}" data-action="gallery" data-index="${i}" aria-label="View photograph ${i+1}" aria-pressed="${!i}"><img src="${im.src}" alt="" loading="lazy"></button>`).join('')}</div><p class="gallery-note" id="gallery-caption">${esc(img.type)} · 1 / ${v.gallery.length}. Original photographs define product details.</p></div><div class="pdp-info"><span class="eyebrow">${esc(p.category)}</span><h1>${esc(p.name)}</h1><p class="source-alias">Proposed name · Original catalog: ${esc(p.sourceName)}</p><p class="desc">${esc(p.description)}</p><div class="price-line">Price to be confirmed<small>Stock and launch availability are pending. No live orders are accepted.</small></div><label class="variant-label">Catalog option: <b style="font-weight:400">${esc(v.label)}</b></label><div class="variant-buttons">${p.variants.map((vv,i)=>`<button data-action="variant" data-index="${i}" class="${i===vi?'active':''}" aria-pressed="${i===vi}">${esc(vv.label)}</button>`).join('')}</div>${!p.verifiedOriginals||p.materialUncertain?`<div class="notice"><b>${!p.verifiedOriginals?'Original photography needed.':'Material verification needed.'}</b><br>${!p.verifiedOriginals?'Only AI images were supplied for this family. Its construction and catalog options need checking.':'The source folder flags an unresolved material question.'} This product cannot be added to the review checkout.</div>`:''}<div class="purchase-row"><div class="quantity" aria-label="Quantity"><button data-action="pdp-minus" aria-label="Decrease quantity">−</button><output id="pdp-qty">${qty}</output><button data-action="pdp-plus" aria-label="Increase quantity">+</button></div><button class="button" data-action="add" ${!p.verifiedOriginals||p.materialUncertain?'disabled':''}>Add to review bag ${arrow}</button></div><p class="small-note">Try the shopping experience. This bag is saved only in this browser.</p><div class="specs"><details open><summary>Product details & materials</summary><dl><dt>Construction</dt><dd>${esc(p.materials)}</dd><dt>Option</dt><dd>${esc(v.label)} (source folder label)</dd><dt>Capacity</dt><dd>${esc(v.capacity||'To be confirmed. Model numbers are not treated as capacity.')}</dd><dt>Dimensions</dt><dd>${esc(v.dimensions||'To be confirmed from supplier specifications.')}${v.dimensionImage?` <a class="text-button" href="${v.dimensionImage}" target="_blank" rel="noopener">View source diagram ↗</a>`:''}</dd><dt>Set contents</dt><dd>Quantity and included accessories need confirmation. Images show the supplied catalog presentation.</dd></dl></details><details><summary>Care & compatibility</summary><p>Product-specific cleaning, heat-source compatibility, electrical ratings where relevant, and dishwasher guidance have not been confirmed. No grade, certification, temperature performance, or warranty is assumed.</p></details><details><summary>Delivery & returns</summary><p>Shipping rates, serviceable areas, delivery estimates, returns eligibility and contact details are pending. <a class="text-button" href="#/policy/shipping">View the draft shipping page</a>.</p></details><details><summary>Image & catalog sources</summary><p>${p.originalCount} original images and ${p.aiCount} AI images supplied for this family. The lead courtyard image is AI-assisted. Original photographs follow it where supplied and define the product details. Images are displayed at their natural aspect ratios without stretching or cropping.</p><p class="source-list">Source family: ${esc(p.sourceFamily)}<br>Current image: ${esc(img.sourcePath)}</p></details></div></div></div>${scene?`<div class="pdp-lifestyle">${photo(scene)}<div><span class="eyebrow">IN THE EVERYDAY</span><h2>${{cook:'The first sizzle.',gather:'A place at your table.',pause:'Make room for a moment.',carry:'A little home, carried.'}[scene]}</h2><p>AI-assisted courtyard scene. Check the original photographs in the gallery for construction, colours and markings.</p></div></div>`:''}<div class="related"><h2>A few familiar companions.</h2><div class="products">${catalog.filter(pp=>pp.category===p.category&&pp.id!==p.id).slice(0,4).map(card).join('')}</div></div></article>`}
function currentPDP(){const el=$('.pdp');if(!el)return {};const p=product(el.dataset.product);return {p,v:p.variants.find(v=>v.id===el.dataset.variant)}}
function addToBag(){const {p,v}=currentPDP();if(!p?.verifiedOriginals||p.materialUncertain)return;const item=cart.find(x=>x.id===p.id&&x.variant===v.id);if(item)item.qty=Math.min(99,item.qty+pdpQty);else cart.push({id:p.id,variant:v.id,qty:pdpQty});saveStore('atelier-review-bag',cart);updateBagCount();bag();toast('Added to your review bag')}
function quantityControl(i,x){return `<div class="quantity"><button data-action="bag-minus" data-index="${i}" aria-label="Decrease ${esc(product(x.id).name)} quantity">−</button><output>${x.qty}</output><button data-action="bag-plus" data-index="${i}" aria-label="Increase ${esc(product(x.id).name)} quantity">+</button></div>`}
function bag(){const d=$('#bag-dialog');d.className='bag-dialog';d.innerHTML=`<div class="dialog-top"><h2>Your review bag <span style="font:12px var(--sans)">(${cart.reduce((s,x)=>s+x.qty,0)})</span></h2><button class="close" data-action="close" aria-label="Close bag">×</button></div><div class="bag-body">${cart.length?cart.map((x,i)=>{const p=product(x.id),v=p.variants.find(v=>v.id===x.variant);return `<div class="bag-item"><a href="${productUrl(p,v.id)}"><img src="${v.gallery[0].src}" alt="${esc(p.name)}"></a><div><a href="${productUrl(p,v.id)}"><h3>${esc(p.name)}</h3></a><small>${esc(v.label)} · Price pending</small><div class="bag-item-tools">${quantityControl(i,x)}<button class="remove" data-action="bag-remove" data-index="${i}">Remove</button></div></div></div>`}).join(''):'<div class="empty"><h2>Room for the everyday.</h2><p>Take a closer look at the objects you know.</p><a class="button" href="#/shop">Explore the collection '+arrow+'</a></div>'}</div>${cart.length?`<div class="bag-foot"><div class="totals"><span>Product prices</span><span>Pending</span></div><div class="totals"><span>Shipping & taxes</span><span>To be confirmed</span></div><a class="button full" href="#/checkout">Try the guest checkout ${arrow}</a><p class="small-note">Review mode · No payment or fulfillment</p><button class="text-button" data-action="close" style="display:block;margin:10px auto 0">Continue exploring</button></div>`:''}`;if(!d.open)d.showModal()}
function modifyBag(i,change){if(!cart[i])return;if(change===0)cart.splice(i,1);else cart[i].qty=Math.max(1,Math.min(99,cart[i].qty+change));saveStore('atelier-review-bag',cart);updateBagCount();bag()}
function search(){const d=$('#search-dialog');d.className='search-dialog';d.innerHTML=`<div class="dialog-top"><span class="eyebrow">A CLOSER LOOK</span><button class="close" data-action="close" aria-label="Close search">×</button></div><div class="search-body"><form id="search-form"><div class="search-input-wrap">${icon('search')}<input type="search" id="global-search" placeholder="Find your everyday…" aria-label="Search product names and options" autocomplete="off"><button type="submit" class="icon-button" aria-label="See all search results">${arrow}</button></div></form><p class="search-hint">Try “Kadai”, “Olivia”, “lunch” or a colour.</p><div class="suggestions" id="search-results"></div></div>`;d.showModal();searchResults('');$('#global-search').focus()}
function searchResults(q){const matches=catalog.filter(p=>!q||matchProduct(p,q));$('#search-results').innerHTML=(q?`<p class="small-note">${matches.length} product families found</p>`:'<span class="eyebrow">FAMILIAR FAVOURITES</span>')+matches.slice(0,5).map(p=>`<a href="${productUrl(p)}"><img src="${p.variants[0].gallery[0].src}" alt=""><span>${esc(p.name)}<small>${esc(p.category)}</small></span><span style="margin-left:auto">↗</span></a>`).join('')+(q&&!matches.length?'<p class="small-note">No matches yet. Try a different name or browse all objects.</p>':'')+`<a class="text-link" href="#/shop${q?'?q='+encodeURIComponent(q):''}">${q?'View all results':'Browse all objects'} ${arrow}</a>`}
function menu(){const d=$('#menu-dialog');d.className='menu-dialog';d.innerHTML=`<div class="dialog-top">${wordmark()}<button class="close" data-action="close" aria-label="Close navigation">×</button></div><nav class="menu-body"><a href="#/shop">All objects</a><a href="#/collections">The collections</a><a href="#/names">The naming study</a><a href="#/story">Our perspective</a><a href="#/account">Guest orders</a><a href="#/help">Help & care</a><a href="#/launch">Review notes</a></nav>`;d.showModal()}
function orderItems(items){return items.map(x=>{const p=product(x.id),v=p?.variants.find(v=>v.id===x.variant);return p&&v?`<div class="order-item"><img src="${v.gallery[0].src}" alt="${esc(p.name)}"><div>${esc(p.name)}<small>${esc(v.label)} · Qty ${x.qty}</small><small>Price to be confirmed</small></div></div>`:''}).join('')}
function checkout(){if(!cart.length)return `<div class="content-page narrow"><div class="empty"><h1>Your bag is waiting.</h1><p>Add an object to try the checkout flow.</p><a class="button" href="#/shop">Explore the collection ${arrow}</a></div></div>`;return `<div class="content-page"><div class="breadcrumb"><a href="#/shop">Shop</a><span>/</span><button class="text-button" data-action="bag">Bag</button><span>/</span><span>Guest checkout</span></div><h1 class="checkout-title">A place in your everyday.</h1><div class="test-banner"><b>CHECKOUT REHEARSAL</b> · No payment will be taken and no order will be sent. Use sample details. Only your review reference, email and selected items are saved in this browser; your address is not saved.</div><div class="two-col"><form id="checkout-form" class="form-card"><h2>1. Guest details</h2><div class="form-grid"><label class="field span2">Email<input name="email" type="email" autocomplete="off" placeholder="review@example.com" required maxlength="180"></label><label class="field">First name<input name="firstName" autocomplete="off" placeholder="Sample" required maxlength="60"></label><label class="field">Last name<input name="lastName" autocomplete="off" placeholder="Customer" required maxlength="60"></label><label class="field span2">Address<input name="address" autocomplete="off" placeholder="12 Sample Street" required maxlength="180"></label><label class="field">City<input name="city" autocomplete="off" placeholder="Mumbai" required maxlength="80"></label><label class="field">PIN code<input name="pin" inputmode="numeric" pattern="[0-9]{6}" title="Enter a six-digit Indian PIN code" autocomplete="off" placeholder="400001" required></label><label class="field">State<input name="state" autocomplete="off" placeholder="Maharashtra" required maxlength="80"></label><label class="field">Country<select name="country"><option>India — review market</option></select></label></div><h2 style="margin-top:30px">2. Delivery & payment</h2><p class="small-note">Delivery coverage, shipping charges and taxes are pending. A PIN code entered here is not a serviceability check.</p><div class="notice">Payment provider is not connected. There is no card, UPI, wallet, or cash-on-delivery transaction in this review.</div><label class="check"><input type="checkbox" required name="reviewConsent">I understand this creates a local test reference only.</label><button class="button full" type="submit">Save a test order reference ${arrow}</button></form><aside class="order-summary"><h2>Your selection.</h2>${orderItems(cart)}<div class="totals big"><span>Total</span><span>Not calculated</span></div><p class="small-note">Product prices, tax rules, shipping and stock must be supplied before an actual total can be calculated.</p><a class="text-link" href="#/launch">Payment & launch setup ${arrow}</a></aside></div></div>`}
function confirmation(id){const o=orders.find(x=>x.id===id);if(!o)return notFound('Review reference not found in this browser.');return `<div class="content-page narrow"><span class="success-mark" aria-hidden="true">✓</span><span class="eyebrow">LOCAL CHECKOUT REHEARSAL COMPLETE</span><h1>Your selection,<br>ready to revisit.</h1><p>Reference <b>${esc(o.id)}</b><br>This is a saved test selection. No purchase, payment, shipment or email confirmation has been created.</p><div class="notice">Saved in this browser on ${new Date(o.created).toLocaleDateString('en-GB')}. Use the reference and your test email to look it up.</div>${orderItems(o.items)}<div class="button-row"><a class="button" href="#/track?reference=${encodeURIComponent(o.id)}">View review status ${arrow}</a><button class="button outline" data-action="download-order" data-id="${o.id}">Download test summary</button></div><p class="small-note">For a live launch, order creation, confirmation emails and tracking must be connected to a backend.</p></div>`}
function tracking(params){return `<div class="content-page narrow"><span class="eyebrow">GUEST ORDER LOOKUP</span><h1>Keep a little<br>closer.</h1><p>Look up a test selection saved in this browser. Live order tracking will be connected before launch.</p><form id="tracking-form" class="form-card"><h2>Find a review reference.</h2><label class="field">Review reference<input name="reference" required placeholder="REVIEW-…" value="${esc(params.get('reference')||'')}" autocomplete="off"></label><label class="field">Test email used at checkout<input name="email" type="email" required placeholder="review@example.com" autocomplete="off"></label><button class="button" type="submit">Look up reference ${arrow}</button><div id="tracking-result" aria-live="polite"></div></form></div>`}
function account(){return `<div class="content-page narrow"><span class="eyebrow">NO ACCOUNT NEEDED TO EXPLORE</span><h1>Your everyday,<br>at a glance.</h1><p>This review uses a guest flow. Your bag and test selections stay in this browser. Account sign-in and cross-device order history will be available only after a secure customer system is connected.</p><div class="button-row"><a class="button" href="#/track">Look up a review reference ${arrow}</a><a class="button outline" href="#/shop">Continue exploring</a></div><h2>Saved test selections</h2>${orders.length?orders.map(o=>`<div class="policy-block"><p>${esc(o.id)} · ${new Date(o.created).toLocaleDateString('en-GB')} · ${o.items.reduce((s,x)=>s+x.qty,0)} items</p><a class="text-link" href="#/confirmation/${o.id}">Revisit selection ${arrow}</a></div>`).join(''):'<p class="small-note">No test selections have been saved here.</p>'}<div class="button-row"><button class="text-button" data-action="clear-data">Clear this browser’s review data</button></div></div>`}
function story(){return `<div class="content-page narrow"><span class="eyebrow">OUR PERSPECTIVE</span><h1>See steel<br>differently.</h1><p>Steel has always had a place in our kitchens.</p><p>In the pan that comes out before everyone arrives. In the dish passed across the table. In the cup held a little longer while the conversation continues.</p><p>We believe it deserves a place in the way we imagine a beautiful home, too.</p>${photo('gather')}<h2>Familiar, seen anew.</h2><p>Look closer. At the curve of a vessel. At light moving across its surface. At familiar forms becoming part of a beautiful setting.</p><p>These are the objects around which everyday life unfolds. The first preparation. The shared meal. The afternoon pause. The little piece of home carried into the day.</p><p>Our story brings these moments into focus, revealing the pleasure, presence, and beauty within them.</p><a class="button" href="#/shop">Find your everyday ${arrow}</a><p class="image-credit">Lifestyle scene created with AI from product references. Brand name pending.</p></div>`}
function help(){return `<div class="content-page narrow"><span class="eyebrow">HELP & CARE</span><h1>A little care.<br>A familiar ritual.</h1><p>Find what is known about the collection, and what still needs confirming before it reaches your home.</p><div class="specs"><details open><summary>Can I place an order?</summary><p>This is a preview storefront. You can explore products, select catalog options, add originals-backed products to a review bag and rehearse guest checkout. Prices, stock, payment and fulfillment are pending.</p></details><details><summary>Is every product entirely stainless steel?</summary><p>No. Some catalog families list steel interiors with coloured exteriors or other components. Complete construction, grades and care must be confirmed for each product. Aroma, Eva and Munch have explicit unresolved material flags.</p></details><details><summary>How do I find product sizes and dimensions?</summary><p>Product options follow the original folder labels. Explicit ml labels are shown with their source. Model numbers such as Kadai 11 or Olivia 2500 are not assumed to be dimensions or capacity. Supplier verification is required before launch.</p></details><details><summary>Which images should I use to judge the product?</summary><p>Original product photographs define shape, colour, markings, handles and construction. The lead courtyard scenes are AI-assisted; original photographs remain available in the product galleries. AI-only families are visibly marked and excluded from review checkout.</p></details><details><summary>How should I clean or use a product?</summary><p>Product-specific care, heat-source compatibility, dishwasher suitability, electrical ratings and performance claims are pending supplier guidance. These will be provided on the relevant product pages before ordering opens.</p></details><details><summary>Where are delivery and return details?</summary><p>The shipping and returns pages identify the missing policy decisions. No delivery speed, return window or warranty has been assumed.</p></details></div><div class="button-row"><a class="button" href="#/support">Contact & support ${arrow}</a><a class="button outline" href="#/track">Review order lookup</a></div></div>`}
function support(){return `<div class="content-page narrow"><span class="eyebrow">CONTACT & SUPPORT</span><h1>Here for the<br>everyday questions.</h1><p>Customer-service email, phone, hours and the returns address are pending. This review form creates a copyable draft; it does not send a message.</p><form id="support-form" class="form-card"><h2>Prepare a support request.</h2><label class="field">Topic<select name="topic"><option>Product information</option><option>Delivery</option><option>Return request</option><option>Order question</option></select></label><label class="field">Reference (optional)<input name="reference" maxlength="80" placeholder="Order or product name"></label><label class="field">Message<textarea name="message" required maxlength="3000" placeholder="What would you like to know?"></textarea></label><button class="button" type="submit">Create a message draft ${arrow}</button><div id="support-result" role="status"></div></form></div>`}
const policies={shipping:{title:'Shipping & delivery.',intro:'A clear route from our collection to your home starts with confirmed delivery details.',sections:[['Where we deliver','Serviceable regions and PIN codes need to be supplied. The review checkout is set up for an India launch concept; it does not confirm coverage.','Confirm the launch market and serviceability data.'],['Charges & timeframes','Shipping rates, free-shipping thresholds, dispatch times and delivery estimates are pending.','Approve rates, processing times, courier partners and delay handling.'],['Tracking & delivery issues','Live carrier updates, lost or damaged parcel handling and customer support channels must be connected.','Confirm carrier integration and escalation process.']]},returns:{title:'Returns, thoughtfully handled.',intro:'The returns experience needs a confirmed policy before ordering opens.',sections:[['Eligibility & return window','The return period, eligible conditions, exceptions and proof-of-purchase requirements are pending.','Approve eligibility, exclusions and the return window.'],['How to request a return','The support address, return address, approval workflow and return-shipping responsibility are pending.','Supply contact details and the return procedure.'],['Refunds & replacements','Refund method, timing, inspection process and replacement rules are pending.','Approve refund and replacement terms.']]},privacy:{title:'Your privacy.',intro:'This review explains its current browser-only storage. A complete approved privacy notice is required for a live store.',sections:[['What this review stores','Your review bag, test reference, test email and selected items are saved in localStorage on this browser. Checkout addresses are not saved. No payment fields, analytics or customer messaging service are connected.','Use sample details during testing.'],['How to remove local data','Use “Clear this browser’s review data” on the Guest orders page or clear this site’s browser storage. It removes the bag and saved test selections.','This device may still send normal hosting requests to load pages and assets.'],['Before the live launch','The business identity, contact details, data controller, processing purposes, payment and shipping processors, retention periods and rights process must be documented and approved.','Complete the live privacy and consent setup.']]},terms:{title:'Terms of the everyday.',intro:'Draft outline for review. These are not approved trading terms; transactions are disabled.',sections:[['Seller & product information','Legal seller identity, registered address, contact details, tax registrations where applicable and confirmed product specifications are pending.','Supply and approve seller information.'],['Orders, prices & payments','Product prices, currency, tax treatment, stock rules, payment provider, order-acceptance process and cancellation terms need confirmation. A local test reference is not an accepted order.','Approve trading terms and enable verified server-side order creation.'],['Delivery, returns & disputes','Shipping, returns, refunds, consumer-rights wording, governing terms and the dispute process need approval for the actual launch market.','Review the final policies with the business before public launch.']]}};
function policy(type){const p=policies[type];if(!p)return notFound();return `<div class="content-page narrow"><span class="legal-label">POLICY DRAFT · BUSINESS APPROVAL PENDING</span><h1>${p.title}</h1><p>${p.intro}</p>${p.sections.map(s=>`<section class="policy-block"><h2>${s[0]}</h2><p>${s[1]}</p><p class="pending">PENDING: ${s[2]}</p></section>`).join('')}<div class="button-row"><a class="text-link" href="#/support">Contact & support ${arrow}</a><a class="text-link" href="#/launch">Launch requirements ${arrow}</a></div></div>`}
function launch(){return `<div class="content-page"><span class="eyebrow">STOREFRONT PREVIEW · LAUNCH CONTROL</span><h1>Taking shape.<br>Ready for a closer look.</h1><p>The visual direction is “See steel differently” in an ancient-India-inspired Courtyard Edit, evolved from Emerald Atelier. All 72 product names are a creative study, not cleared names. Atelier 00 is a clearly temporary wordmark. The approved brand name remains open; none of the explored names has been treated as cleared.</p><div class="launch-grid"><div class="launch-number"><b>${stats.families}</b><span>product-family folders</span></div><div class="launch-number"><b>${stats.originals}</b><span>original product photographs</span></div><div class="launch-number"><b>${stats.ai}</b><span>supplied AI images</span></div></div><h2>What you can review now</h2><table class="status-table"><thead><tr><th>Experience</th><th>Current state</th></tr></thead><tbody><tr><td>Catalog & discovery</td><td>All 72 families, collections, text search, source-colour filters, original-photo filter, sorting and product galleries.</td></tr><tr><td>Catalog options</td><td>${stats.variantGroups} source-folder groups exposed for review. These are not a verified SKU count. Originals determine selectable options when supplied.</td></tr><tr><td>Bag & checkout</td><td>Browser-local bag, quantity changes, removal and guest checkout rehearsal. No calculated prices, payment or real order submission.</td></tr><tr><td>Confirmation & lookup</td><td>Local test reference, downloadable summary and reference/email lookup in the same browser. No email, SMS or carrier service is connected.</td></tr><tr><td>Support & accounts</td><td>Copyable support drafts and guest selections. No message delivery, identity provider or cross-device history.</td></tr><tr><td>Policies</td><td>Draft shipping, returns, privacy and terms pages show decisions still required.</td></tr></tbody></table><h2>Product truth & photography</h2><p>${stats.originalFamilies} families contain original photographs. AI-only families are marked and excluded from the review checkout: ${esc(stats.aiOnlyFamilies.join(', '))}. Aroma, Eva and Munch require material confirmation. Product markings visible in original images have been preserved; branding rights need checking.</p><p>The Courtyard Edit adds a proposed name and an AI-assisted courtyard scene for each of the 72 product families. The earlier seven lifestyle compositions remain in the source archive. The generated courtyard scenes lead the shopping experience. Their natural image ratios are preserved without cropping or stretching. Original source photos remain in the galleries for product-fidelity checks. Both kettle listings remain removed.</p><h2>Specific setup needed for live commerce</h2><ol><li>Choose and clear the final brand name. Confirm legal seller identity, domain, customer-service details and approved product-image usage.</li><li>Supply supplier SKUs, prices, currency, tax treatment, inventory, approved set contents, dimensions, capacity, materials, care and compatibility.</li><li>Approve shipping rates, serviceability, dispatch estimates, return/refund rules and final privacy and trading terms.</li><li>Connect a commerce backend with server-side catalog prices, stock reservations, order records and a verified payment-provider account. A provider such as Razorpay can be integrated after business setup; no provider account has been created or chosen here.</li><li>Create server-only payment orders. Verify signed payment webhooks, reconcile the amount and currency against server prices, and use idempotency before recording a paid order. Do not mark an order paid from a browser callback.</li><li>Connect transactional email, support delivery and carrier tracking. Add secure customer authentication only if accounts are enabled.</li><li>Test sandbox payment success, failure, cancellation, duplicate webhooks, refunds, stock changes and mobile checkout. Show the final configuration for your approval before public access or live transactions.</li></ol><div class="notice"><b>Launch remains closed.</b> This preview site does not accept orders or payments. Live transactions require explicit business approval.</div><div class="button-row"><a class="button" href="#/">Return to the experience ${arrow}</a><a class="button outline" href="#/shop">Review the catalog</a></div></div>`}
function notFound(message='The page you’re looking for isn’t here.'){return `<div class="content-page narrow"><h1>A different turn.</h1><p>${esc(message)}</p><a class="button" href="#/">Back to the everyday ${arrow}</a></div>`}
function closeDialogs(){$$('dialog[open]').forEach(d=>d.close())}
function route(){closeDialogs();const u=new URL((location.hash.slice(1)||'/'),location.origin);const path=u.pathname.split('/').filter(Boolean);let html,title='See steel differently';pdpQty=1;if(!path.length||path[0]==='home'){html=home()}else switch(path[0]){case'shop':html=shop(u.searchParams);title=shopState.category||'All objects';break;case'names':html=namingStudy();title='The courtyard naming study';break;case'collections':html=collections();title='The collections';break;case'product':{const p=product(path[1]);const vi=p?Math.max(0,p.variants.findIndex(v=>v.id===(u.searchParams.get('variant')||p.heroVariant))):0;html=p?renderProduct(p,vi):notFound();title=p?.name||'Product not found';break}case'checkout':html=checkout();title='Guest checkout rehearsal';break;case'confirmation':html=confirmation(path[1]);title='Test selection saved';break;case'track':html=tracking(u.searchParams);title='Review reference lookup';break;case'account':html=account();title='Guest orders';break;case'story':html=story();title='Our perspective';break;case'help':html=help();title='Help & care';break;case'support':html=support();title='Contact & support';break;case'policy':html=policy(path[1]);title='Policy draft';break;case'launch':html=launch();title='Launch & review notes';break;default:html=notFound()};$('#main').innerHTML=html;document.title=`${title} — Atelier 00 storefront preview`;window.scrollTo({top:0,behavior:'instant'});if(path[0]==='shop')updateShop();if(u.searchParams.get('chapter'))setTimeout(()=>document.getElementById(u.searchParams.get('chapter'))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}),50)}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function download(data,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'instant'});return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;switch(action){case'close':b.closest('dialog')?.close();break;case'search':search();break;case'menu':menu();break;case'bag':bag();break;case'add':addToBag();break;case'pdp-minus':pdpQty=Math.max(1,pdpQty-1);$('#pdp-qty').value=pdpQty;break;case'pdp-plus':pdpQty=Math.min(99,pdpQty+1);$('#pdp-qty').value=pdpQty;break;case'variant':{const{p}=currentPDP();$('#main').innerHTML=renderProduct(p,+b.dataset.index,pdpQty);history.replaceState(null,'',productUrl(p,p.variants[+b.dataset.index].id));break}case'gallery':{const{v}=currentPDP(),i=+b.dataset.index;$('#product-main-image').src=v.gallery[i].src;$('#gallery-caption').textContent=`${v.gallery[i].type} · ${i+1} / ${v.gallery.length}. Original photographs define product details.`;$$('.gallery-thumbs button').forEach((b,idx)=>{b.classList.toggle('active',i===idx);b.setAttribute('aria-pressed',i===idx)});break}case'zoom':{const d=$('#image-dialog');d.className='image-dialog';d.innerHTML=`<button class="close" data-action="close" aria-label="Close enlarged image">×</button><img src="${$('#product-main-image').src}" alt="${esc($('#product-main-image').alt)}">`;d.showModal();break}case'bag-minus':modifyBag(+b.dataset.index,-1);break;case'bag-plus':modifyBag(+b.dataset.index,1);break;case'bag-remove':modifyBag(+b.dataset.index,0);break;case'filter-category':shopState.category=b.dataset.category;$$('.filter-cat').forEach(x=>x.classList.toggle('active',x===b));$('.page-head h1').textContent=shopState.category||'Familiar forms. A fresh spirit.';updateShop();break;case'reset-filters':location.hash='#/shop';if(!location.hash.includes('?')){shopState={category:'',q:'',color:'',verified:false,sort:'featured'};$('#main').innerHTML=shop(new URLSearchParams);updateShop()}break;case'carry-step':{const i=+b.dataset.step,key=['carry','carry-close','carry-bag'][i];$('#carry-image').innerHTML=photo(key)+`<span class="photo-caption">The Sleek lunchbox · ${['Pack a little home','Close the familiar lid','Take it into the day'][i]}</span>`;$$('.carry-steps button').forEach((bb,j)=>bb.setAttribute('aria-selected',i===j));break}case'download-order':{const o=orders.find(o=>o.id===b.dataset.id);if(o)download({mode:'LOCAL REVIEW ONLY — NOT A PURCHASE',reference:o.id,created:o.created,items:o.items.map(x=>({product:product(x.id).name,option:product(x.id).variants.find(v=>v.id===x.variant).label,quantity:x.qty})),payment:'Not connected',fulfillment:'No shipment created',prices:'Pending'},o.id+'.json');break}case'clear-data':cart=[];orders=[];saveStore('atelier-review-bag',cart);saveStore('atelier-review-orders',orders);updateBagCount();route();toast('Review data cleared from this browser');break;case'copy-support':navigator.clipboard?.writeText($('#support-draft').value).then(()=>toast('Support draft copied')).catch(()=>toast('Select the draft text to copy it.'));break}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='catalog-search'){shopState.q=e.target.value;updateShop()}});
document.addEventListener('change',e=>{if(e.target.id==='color-filter')shopState.color=e.target.value;else if(e.target.id==='verified-filter')shopState.verified=e.target.checked;else if(e.target.id==='sort-filter')shopState.sort=e.target.value;else return;updateShop()});
document.addEventListener('submit',e=>{const form=e.target;const data=new FormData(form);if(form.id==='search-form'){e.preventDefault();location.hash='#/shop?q='+encodeURIComponent(data.get('q')||$('#global-search').value);closeDialogs()}else if(form.id==='checkout-form'){e.preventDefault();if(!cart.length)return;const id='REVIEW-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();orders.unshift({id,email:String(data.get('email')).trim().toLowerCase(),created:new Date().toISOString(),items:cart.map(x=>({...x}))});orders=orders.slice(0,30);saveStore('atelier-review-orders',orders);cart=[];saveStore('atelier-review-bag',cart);updateBagCount();location.hash='#/confirmation/'+id}else if(form.id==='tracking-form'){e.preventDefault();const o=orders.find(o=>o.id===String(data.get('reference')).trim().toUpperCase()&&o.email===String(data.get('email')).trim().toLowerCase());$('#tracking-result').innerHTML=o?`<div class="notice"><b>${esc(o.id)}</b><br>Test selection saved locally. No payment received; no parcel exists.</div><div class="timeline"><div>Review selection saved<small>${new Date(o.created).toLocaleString('en-GB')}</small></div><div>Live order acceptance<small>Not enabled</small></div><div>Dispatch & delivery<small>No shipment created</small></div></div><a class="text-link" href="#/confirmation/${o.id}">View the selection ${arrow}</a>`:'<p class="error-message">No matching review reference and email were found in this browser. Check both fields. Live order lookup is not connected.</p>'}else if(form.id==='support-form'){e.preventDefault();const msg=`Topic: ${data.get('topic')}\nReference: ${data.get('reference')||'Not supplied'}\n\n${data.get('message')}`;$('#support-result').innerHTML=`<label class="field" style="margin-top:22px">Your draft — not sent<textarea id="support-draft" readonly>${esc(msg)}</textarea></label><button class="text-button" type="button" data-action="copy-support">Copy draft</button><p class="small-note">A customer-service address needs to be supplied before messages can be sent.</p>`}});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('hashchange',route);
document.addEventListener('keydown',e=>{const t=e.target.closest('.carry-steps [role="tab"]');if(!t||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('.carry-steps [role="tab"]');const i=tabs.indexOf(t);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()});
fetch('catalog.json?v=scenes-3').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json()}).then(data=>{catalog=data.products;stats=data.stats;cart=cart.filter(x=>{const p=product(x?.id);return p?.verifiedOriginals&&!p.materialUncertain&&p.variants.some(v=>v.id===x.variant)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99});orders=orders.filter(o=>o&&typeof o.id==='string'&&typeof o.email==='string'&&Array.isArray(o.items)&&Number.isFinite(Date.parse(o.created))&&o.items.every(x=>product(x.id)?.variants.some(v=>v.id===x.variant)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99));chrome();route()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>A moment, please.</h1><p>The product catalog could not be loaded. Reload to try again.</p><button class="button" onclick="location.reload()">Reload the collection</button></div>'});


